const crypto = require('crypto');
const ALLOWED_MIMES = new Set(['application/pdf', 'image/jpeg', 'image/png']);
const MAX_BYTES = 10 * 1024 * 1024;

const item = $input.first();
const binaryKeys = Object.keys(item.binary || {});
if (binaryKeys.length === 0) {
  throw new Error('No binary file attached to form submission');
}

const binaryKey = binaryKeys[0];
const meta = item.binary[binaryKey];
if (!ALLOWED_MIMES.has(meta.mimeType)) {
  throw new Error(`Unsupported MIME type: ${meta.mimeType}`);
}

const buffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
if (buffer.length > MAX_BYTES) {
  throw new Error(`File exceeds 10 MB limit (${buffer.length} bytes)`);
}

const fileHash = crypto.createHash('sha256').update(buffer).digest('hex');

return [
  {
    json: {
      file_hash: fileHash,
      file_name: meta.fileName || 'invoice',
      mime_type: meta.mimeType,
      file_size_bytes: buffer.length,
      submitter_email: item.json['Submitter Email'] || null,
      base64_data: buffer.toString('base64')
    }
  }
];

const response = $input.first().json;
const rawText = response?.choices?.[0]?.message?.content;
if (!rawText || typeof rawText !== 'string') {
  throw new Error('NVIDIA response missing structured JSON text payload');
}

let parsed;
try {
  parsed = JSON.parse(rawText);
} catch (error) {
  throw new Error(`Malformed JSON from NVIDIA: ${error.message}`);
}

return [
  {
    json: {
      vendor_name: String(parsed.vendor_name ?? '').trim(),
      invoice_number: String(parsed.invoice_number ?? '').trim(),
      po_number: parsed.po_number ? String(parsed.po_number).trim() : null,
      invoice_date: String(parsed.invoice_date ?? '').trim(),
      due_date: parsed.due_date ? String(parsed.due_date).trim() : null,
      currency: String(parsed.currency ?? '').trim().toUpperCase(),
      line_items: Array.isArray(parsed.line_items) ? parsed.line_items : [],
      subtotal: Number(parsed.subtotal),
      tax_amount: Number(parsed.tax_amount ?? 0),
      shipping_amount: Number(parsed.shipping_amount ?? 0),
      discount_amount: Number(parsed.discount_amount ?? 0),
      total_amount: Number(parsed.total_amount),
      extraction_confidence: Number(parsed.extraction_confidence),
      extraction_notes: String(parsed.extraction_notes ?? '').trim()
    }
  }
];

const CONFIDENCE_THRESHOLD = 0.85;
const MATH_TOLERANCE_CENTS = 2;
const PO_VARIANCE_TOLERANCE_PERCENT = 0.01;

const toCents = (value) => {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    return null;
  }
  return Math.round(value * 100);
};

const formatMoney = (cents) => (cents / 100).toFixed(2);
const normalizeKey = (value) => String(value ?? '').trim().toUpperCase();

const invoice = $('Normalize NVIDIA Payload').first().json;
const fileMeta = $('Validate File & Prep Payload').first().json;

const ledgerRows = $('Fetch Ledger History')
  .all()
  .map((item) => item.json)
  .filter((row) => row && (row.invoice_number || row.file_hash));
const poRecords = $('Fetch Matching PO')
  .all()
  .map((item) => item.json)
  .filter((po) => po && po.po_number);

const flags = [];
const pushFlag = (code, severity, detail) => {
  flags.push({ code, severity, detail });
};

for (const field of ['vendor_name', 'invoice_number', 'invoice_date', 'currency']) {
  if (!invoice[field]) {
    pushFlag('REQUIRED_FIELD_MISSING', 'CRITICAL', `Missing required field: ${field}`);
  }
}

if (!Array.isArray(invoice.line_items) || invoice.line_items.length === 0) {
  pushFlag('NO_LINE_ITEMS', 'CRITICAL', 'Invoice contains zero extractable line items');
}

if (!Number.isFinite(invoice.extraction_confidence) || invoice.extraction_confidence < CONFIDENCE_THRESHOLD) {
  pushFlag('LOW_EXTRACTION_CONFIDENCE', 'HIGH', `Extraction confidence ${invoice.extraction_confidence} is below threshold ${CONFIDENCE_THRESHOLD}`);
}

const invoiceKey = `${normalizeKey(invoice.vendor_name)}::${normalizeKey(invoice.invoice_number)}`;
const duplicateRecord = ledgerRows.find((row) => {
  const rowKey = `${normalizeKey(row.vendor_name)}::${normalizeKey(row.invoice_number)}`;
  return rowKey === invoiceKey || (fileMeta.file_hash && row.file_hash === fileMeta.file_hash);
});

if (duplicateRecord) {
  pushFlag('DUPLICATE_INVOICE', 'CRITICAL', `Matches existing ledger entry ${duplicateRecord.invoice_number} (${duplicateRecord.status})`);
}

let computedSubtotalCents = 0;
invoice.line_items.forEach((item, index) => {
  const unitCents = toCents(item.unit_price);
  const lineCents = toCents(item.line_total);
  const quantity = Number(item.quantity);

  if (unitCents === null || lineCents === null || !Number.isFinite(quantity)) {
    pushFlag('INVALID_LINE_ITEM_NUMBER', 'HIGH', `Line ${index + 1} contains non-numeric values`);
    return;
  }

  const expectedLineCents = Math.round(quantity * unitCents);
  if (Math.abs(expectedLineCents - lineCents) > MATH_TOLERANCE_CENTS) {
    pushFlag('LINE_ITEM_MATH_MISMATCH', 'HIGH', `Line ${index + 1} (${item.description}): ${quantity} x ${formatMoney(unitCents)} = ${formatMoney(expectedLineCents)}, printed ${formatMoney(lineCents)}`);
  }
  computedSubtotalCents += lineCents;
});

const statedSubtotalCents = toCents(invoice.subtotal);
const taxCents = toCents(invoice.tax_amount) ?? 0;
const shippingCents = toCents(invoice.shipping_amount) ?? 0;
const discountCents = toCents(invoice.discount_amount) ?? 0;
const statedTotalCents = toCents(invoice.total_amount);
const computedTotalCents = computedSubtotalCents + taxCents + shippingCents - Math.abs(discountCents);

if (statedSubtotalCents === null || statedTotalCents === null) {
  pushFlag('INVALID_TOTALS', 'CRITICAL', 'Subtotal or total_amount is missing or non-numeric');
} else {
  if (Math.abs(computedSubtotalCents - statedSubtotalCents) > MATH_TOLERANCE_CENTS) {
    pushFlag('SUBTOTAL_MISMATCH', 'HIGH', `Line items sum to ${formatMoney(computedSubtotalCents)} but stated subtotal is ${formatMoney(statedSubtotalCents)}`);
  }
  if (Math.abs(computedTotalCents - statedTotalCents) > MATH_TOLERANCE_CENTS) {
    pushFlag('GRAND_TOTAL_MISMATCH', 'HIGH', `Computed total is ${formatMoney(computedTotalCents)} but stated total is ${formatMoney(statedTotalCents)}`);
  }
}

const matchedPo = poRecords.find((po) => normalizeKey(po.po_number) === normalizeKey(invoice.po_number));
let poAuthorizedCents = null;
let poVarianceCents = null;

if (!invoice.po_number) {
  pushFlag('PO_NUMBER_MISSING', 'MEDIUM', 'Invoice does not reference a Purchase Order');
} else if (!matchedPo) {
  pushFlag('PO_NOT_FOUND', 'HIGH', `Referenced PO ${invoice.po_number} does not exist in PO master`);
} else {
  if (normalizeKey(matchedPo.currency) !== normalizeKey(invoice.currency)) {
    pushFlag('CURRENCY_MISMATCH', 'HIGH', `Invoice currency ${invoice.currency} does not match PO currency ${matchedPo.currency}`);
  }
  poAuthorizedCents = toCents(Number(matchedPo.remaining_amount ?? matchedPo.authorized_amount));
  if (poAuthorizedCents !== null && statedTotalCents !== null) {
    poVarianceCents = statedTotalCents - poAuthorizedCents;
    const allowedOverageCents = Math.max(MATH_TOLERANCE_CENTS, Math.round(poAuthorizedCents * PO_VARIANCE_TOLERANCE_PERCENT));
    if (poVarianceCents > allowedOverageCents) {
      pushFlag('PO_AMOUNT_EXCEEDED', 'HIGH', `Invoice total ${formatMoney(statedTotalCents)} exceeds authorized PO balance ${formatMoney(poAuthorizedCents)} by ${formatMoney(poVarianceCents)}`);
    }
  }
}

return [
  {
    json: {
      decision: flags.length === 0 ? 'AUTO_APPROVED' : 'NEEDS_REVIEW',
      flag_count: flags.length,
      file_hash: fileMeta.file_hash,
      submitter_email: fileMeta.submitter_email,
      vendor_name: invoice.vendor_name,
      invoice_number: invoice.invoice_number,
      po_number: invoice.po_number,
      invoice_date: invoice.invoice_date,
      currency: invoice.currency,
      extraction_confidence: invoice.extraction_confidence,
      reconciliation: {
        stated_subtotal_cents: statedSubtotalCents,
        computed_subtotal_cents: computedSubtotalCents,
        stated_total_cents: statedTotalCents,
        computed_total_cents: computedTotalCents,
        po_authorized_cents: poAuthorizedCents,
        po_variance_cents: poVarianceCents
      },
      flags,
      raw_invoice: invoice
    }
  }
];

const audit = $('Deterministic Audit Engine').first().json;
const rec = audit.reconciliation || {};
const reviewerId = 'SYSTEM_AUTO';
return [
  {
    json: {
      invoice_number: String(audit.invoice_number ?? ''),
      vendor_name: String(audit.vendor_name ?? ''),
      po_number: String(audit.po_number ?? ''),
      invoice_date: String(audit.invoice_date ?? ''),
      currency: String(audit.currency ?? ''),
      stated_total: (rec.stated_total_cents ?? 0) / 100,
      computed_total: (rec.computed_total_cents ?? 0) / 100,
      po_variance: (rec.po_variance_cents ?? 0) / 100,
      status: 'APPROVED_AUTO',
      reviewer_id: reviewerId,
      file_hash: String(audit.file_hash ?? ''),
      submitter_email: String(audit.submitter_email ?? ''),
      flags_json: JSON.stringify(audit.flags || []),
      processed_at: new Date().toISOString()
    }
  }
];

const audit = $('Deterministic Audit Engine').first().json;
const rec = audit.reconciliation || {};
return [
  {
    json: {
      invoice_number: String(audit.invoice_number ?? ''),
      vendor_name: String(audit.vendor_name ?? ''),
      po_number: String(audit.po_number ?? ''),
      invoice_date: String(audit.invoice_date ?? ''),
      currency: String(audit.currency ?? ''),
      stated_total: (rec.stated_total_cents ?? 0) / 100,
      computed_total: (rec.computed_total_cents ?? 0) / 100,
      po_variance: (rec.po_variance_cents ?? 0) / 100,
      status: 'PENDING',
      reviewer_id: '',
      file_hash: String(audit.file_hash ?? ''),
      submitter_email: String(audit.submitter_email ?? ''),
      flags_json: JSON.stringify(audit.flags || []),
      requested_at: new Date().toISOString(),
      decided_at: ''
    }
  }
];
